  ('ui.zitounti.failure_not_signed_in', to_jsonb('الجلسة متاعك سالت. ادخل من جديد بنمرة التلفون متاعك، ونبعثولك رمز بالSMS.'::text), 'text', 'ui', 'رسالة: الجلسة سالت', 'فضاء «زيتونتي» (/zitounti): في البطاقة كي الجلسة تسالي بين فتح الصفحة وقراية الملف.', true, 120),
