  ('ui.zitounti.failure_error', to_jsonb('ما نجّمناش نقراو ملفّك توّا. حدّث الصفحة، وإذا تعاودت المشكلة عيّط على فريق AgriZed.'::text), 'text', 'ui', 'رسالة: خطأ في القراية', 'فضاء «زيتونتي» (/zitounti): في البطاقة كي قراية الملف تفشل لسبب آخر.', true, 170),
