  ('ui.zitounti.document_stored_note', to_jsonb('الوثيقة محفوظة عندنا. اطلبها من فريق AgriZed ويبعثهالك.'::text), 'text', 'ui', 'ملاحظة وثيقة محفوظة', 'جزء «الوثائق»: تحت وثيقة عندنا منها نسخة.', true, 920),
  ('ui.zitounti.document_record_note', to_jsonb('هذا مرجع مكتوب، مازال ما عندناش منّو نسخة إلكترونية. عيّط على الفريق إذا تلزمك نسخة.'::text), 'text', 'ui', 'ملاحظة مرجع بلا نسخة', 'جزء «الوثائق»: تحت وثيقة ما عندناش منها نسخة إلكترونية.', true, 930),
  ('ui.zitounti.password_policy_not_applied', to_jsonb('خدمة كلمة السرّ مازالت ما تفعّلتش. جرّب بعد شويّة، ولا كلّمنا.'::text), 'text', 'ui', 'خطأ: خدمة كلمة السرّ موش مفعّلة', 'فضاء «زيتونتي» (/zitounti): شاشة «أنشئ كلمة سرّ» كي قاعدة البيانات مازالت ما فيهاش خدمة كلمة السرّ.', true, 940),
