  ('ui.login.min_length_hint', to_jsonb('على الأقل {count, plural, one {حرف واحد} two {حرفين} few {# أحرف} other {# حرف}}.'::text), 'text', 'ui', 'أقلّ طول لكلمة السرّ', 'صفحة الدخول (/zitounti): تحت خانة كلمة السرّ الجديدة. {count} = أقلّ عدد حروف (من الإعدادات، الكلمة تتبدّل حسب العدد).', true, 1030),
