  ('ui.login.remember_device_hint', to_jsonb('ما تعلّمهاش على تلفون موش متاعك.'::text), 'text', 'ui', 'تنبيه تحت تذكّر الجهاز', 'صفحة الدخول (/zitounti): السطر الصغير تحت «تذكّر هذا الجهاز».', true, 1060),
