  ('ui.login.help_call', to_jsonb('ما نجّمتش تدخل؟ كلّمنا على {phone}'::text), 'text', 'ui', 'طلب المساعدة بالتلفون', 'صفحة الدخول (/zitounti): السطر الأخير تحت الأزرار. {phone} = نمرة الفريق (site.contact_phone)، تتكتب رابط للاتصال.', true, 1170),
  ('ui.login.sign_out', to_jsonb('اخرج من الحساب'::text), 'text', 'ui', 'زرّ الخروج من الحساب', 'صفحة الدخول (/zitounti): تحت شاشة إنشاء كلمة السرّ، للحريف اللي يحبّ يخرج قبل ما يكمّل.', true, 1180),
  ('ui.login.error_invalid_code', to_jsonb('الرمز غالط ولا فات وقتو. شوف الرسالة مرّة أخرى واكتبو كيما هو، ولا اطلب رمز جديد.'::text), 'text', 'ui', 'خطأ: رمز غالط ولا فات وقتو', 'صفحة الدخول (/zitounti) وصفحة الأمان (/zitounti/security): كي الرمز ما يحلّش. جملة وحدة للرمز الغالط والفايت وقتو والمفقود، عن قصد: ما تزيدش تفاصيل.', true, 1190),
  ('ui.login.error_invalid_phone', to_jsonb('النمرة موش مكتوبة كيما يلزم. اكتبها بالشكل +216XXXXXXXX.'::text), 'text', 'ui', 'خطأ: نمرة مكتوبة غالط', 'صفحة الدخول (/zitounti) وصفحة الأمان (/zitounti/security): كي النمرة موش بالشكل الصحيح.', true, 1200),
  ('ui.login.error_too_many_attempts', to_jsonb('جرّبت برشة مرّات والرمز تبطّل. اطلب رمز جديد.'::text), 'text', 'ui', 'خطأ: الرمز تبطّل', 'صفحة الدخول (/zitounti) وصفحة الأمان (/zitounti/security): كي الحريف جرّب الرمز برشة مرّات والرمز تلغى.', true, 1210),
  ('ui.login.error_not_applied', to_jsonb('خدمة الدخول مازالت ما تفعّلتش. لازم تتطبّق supabase/migrations/0108_client_password.sql.'::text), 'text', 'ui', 'خطأ: خدمة الدخول موش مفعّلة', 'صفحة الدخول (/zitounti): كي قاعدة البيانات ناقصها التحديث 0108. رسالة تقنية، ما تظهرش في الاستعمال العادي.', true, 1220),
  ('ui.login.error_generic', to_jsonb('تعذّر الدخول توّا. حاول مرّة أخرى، وإذا تعاود المشكل كلّم الفريق.'::text), 'text', 'ui', 'خطأ عام في الدخول', 'صفحة الدخول (/zitounti): كي صار مشكل ما نعرفوش سببو.', true, 1230),
  ('ui.login.error_bad_credentials', to_jsonb('النمرة ولا كلمة السرّ غالطة. تثبّت منهم وعاود، ولا اضغط على «نسيت كلمة السرّ؟».'::text), 'text', 'ui', 'خطأ: النمرة ولا كلمة السرّ غالطة', 'صفحة الدخول (/zitounti): جملة وحدة للنمرة المجهولة وكلمة السرّ الغالطة، عن قصد (باش الفورم ما يكشفش شكون حريف). تذكر اسم الرابط ui.login.forgot_password.', true, 1240),
  ('ui.login.error_too_many_passwords', to_jsonb('جرّبت برشة مرّات. استنّى شويّة وعاود.'::text), 'text', 'ui', 'خطأ: محاولات برشة', 'صفحة الدخول (/zitounti): كي الحريف جرّب كلمة السرّ برشة مرّات، وما نعرفوش قدّاش يستنّى.', true, 1250),
  ('ui.login.error_retry_in', to_jsonb('جرّبت برشة مرّات. استنّى {minutes, plural, one {دقيقة} two {دقيقتين} few {# دقايق} other {# دقيقة}} وعاود.'::text), 'text', 'ui', 'خطأ: محاولات برشة، مع المدّة', 'صفحة الدخول (/zitounti) وصفحة الأمان (/zitounti/security): كي كلمة السرّ تجرّبت برشة مرّات. {minutes} = قدّاش يستنّى بالدقايق (الكلمة تتبدّل حسب العدد).', true, 1260),
  ('ui.login.error_sms_blocked', to_jsonb('ما نجّمناش نبعثو الرمز توّا — خدمة الرسائل موش مضبوطة. كلّم الفريق، ولا جرّب بعد شويّة.'::text), 'text', 'ui', 'خطأ: الرمز ما تبعثش', 'صفحة الدخول (/zitounti) وصفحة الأمان (/zitounti/security): كي خدمة SMS موش مضبوطة والرمز ما خرجش.', true, 1270),
  ('ui.login.error_session_gone', to_jsonb('الجلسة انتهت قبل ما تكمّل. ادخل مرّة أخرى برمز SMS وأنشئ كلمة السرّ.'::text), 'text', 'ui', 'خطأ: الجلسة انتهت', 'صفحة الدخول (/zitounti): كي الجلسة تنتهي قبل ما الحريف يسجّل كلمة السرّ متاعو أوّل مرّة.', true, 1280),
  ('ui.login.error_password_mismatch', to_jsonb('كلمتا السرّ موش كيف كيف. اكتب نفس الكلمة في الزوز.'::text), 'text', 'ui', 'خطأ: كلمتا السرّ مختلفتين', 'صفحة الدخول (/zitounti): كي الخانتين متاع كلمة السرّ الجديدة موش كيف كيف.', true, 1290),
  ('ui.login.error_password_weak', to_jsonb('كلمة السرّ ضعيفة ياسر. اختار وحدة أطول، وخلّط فيها حروف وأرقام.'::text), 'text', 'ui', 'خطأ: كلمة سرّ ضعيفة', 'صفحة الدخول (/zitounti): كي نظام الحسابات يرفض كلمة السرّ على خاطرها ضعيفة.', true, 1300),
  ('ui.login.error_password_exists', to_jsonb('كلمة السرّ موجودة. باش تبدّلها، من صفحة الأمان.'::text), 'text', 'ui', 'خطأ: كلمة السرّ موجودة', 'صفحة الدخول (/zitounti): كي الحريف عندو كلمة سرّ ويحاول ينشئ وحدة أخرى من شاشة الدخول.', true, 1310),
